"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";

type Props = {
  label: string;
  used: number;
  cap: number;
  unit?: string;
  className?: string;
};

export function UsageMeter({ label, used, cap, unit, className }: Props) {
  const reduced = useReducedMotion();
  const pct = cap === Infinity ? 0 : Math.min(100, (used / cap) * 100);
  const color =
    pct < 60
      ? "bg-[var(--color-bull)]"
      : pct < 85
        ? "bg-[var(--color-gold)]"
        : "bg-[var(--color-bear)]";

  const display =
    cap === Infinity
      ? `${used.toLocaleString()} ${unit ?? ""}`.trim()
      : `${used.toLocaleString()} / ${cap.toLocaleString()}${unit ? ` ${unit}` : ""}`;

  return (
    <div className={cn("space-y-1", className)}>
      <div className="flex items-center justify-between text-xs">
        <span className="text-muted-foreground">{label}</span>
        <span className="tabular-nums">{display}</span>
      </div>
      <div className="h-1.5 w-full overflow-hidden rounded-full bg-muted">
        {cap === Infinity ? (
          <div className="h-full w-full bg-[var(--color-gold)] opacity-40" />
        ) : (
          <motion.div
            className={cn("h-full rounded-full", color)}
            initial={reduced ? false : { width: 0 }}
            animate={{ width: `${pct}%` }}
            transition={{ duration: reduced ? 0 : 0.4, ease: "easeOut" }}
          />
        )}
      </div>
    </div>
  );
}
